/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import stringManager from "../../src/i18n/StringManager.js";
import { IntroScreen } from "../../src/intro/IntroScreen.js";
import { ManyWellsScreen } from "../../src/many-wells/ManyWellsScreen.js";
import { OneWellScreen } from "../../src/one-well/OneWellScreen.js";
import { QuantumPotentialPreferencesModel } from "../../src/preferences/QuantumPotentialPreferencesModel.js";
import { TwoWellsScreen } from "../../src/two-wells/TwoWellsScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const screenNames = stringManager.getScreenNames();
  const quantumPotentialPreferences = new QuantumPotentialPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new IntroScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.introStringProperty,
      tandem: Tandem.ROOT.createTandem("introScreen"),
    }),
    new OneWellScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.oneWellStringProperty,
      tandem: Tandem.ROOT.createTandem("oneWellScreen"),
    }),
    new TwoWellsScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.twoWellsStringProperty,
      tandem: Tandem.ROOT.createTandem("twoWellsScreen"),
    }),
    new ManyWellsScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.manyWellsStringProperty,
      tandem: Tandem.ROOT.createTandem("manyWellsScreen"),
    }),
  ];

  return { screens, tracked: { quantumPotentialPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
